from sympy import divisors
def r(n):
    B=int((4*n/3)**0.5)+2
    return sum(1 for a in range(-B,B+1) for b in range(-B,B+1) if a*a-a*b+b*b==n)
for n in range(1,601):
    d=divisors(n)
    assert r(n)==6*(sum(1 for x in d if x%3==1)-sum(1 for x in d if x%3==2))
assert r(91)==24

from math import gcd
def mul(x,y): return (x[0]*y[0]-5*x[1]*y[1], x[0]*y[1]+x[1]*y[0])
def hnf(vecs):
    vecs=[list(v) for v in vecs if tuple(v)!=(0,0)]
    while sum(1 for v in vecs if v[1]!=0)>1:
        nz=sorted([v for v in vecs if v[1]!=0], key=lambda v:abs(v[1]))
        a,b=nz[0],nz[1]; q=b[1]//a[1]
        b[0]-=q*a[0]; b[1]-=q*a[1]
    piv=[v for v in vecs if v[1]!=0][0]
    if piv[1]<0: piv=[-piv[0],-piv[1]]
    h=0
    for v in vecs:
        if v[1]==0: h=gcd(h,abs(v[0]))
    return (h, piv[0]%h, piv[1])
def ideal(gens):
    vs=[]
    for g in gens: vs+= [g, mul(g,(0,1))]
    return hnf(vs)
def prod(A,B): return ideal([mul(a,b) for a in A for b in B])
def index(I): return I[0]*I[2]
P2=[(2,0),(1,1)]; P3=[(3,0),(1,1)]; P3b=[(3,0),(1,-1)]
assert prod(P2,P2)==ideal([(2,0)])
assert prod(P3,P3b)==ideal([(3,0)])
assert prod(P2,P3)==ideal([(1,1)])
assert prod(P2,P3b)==ideal([(1,-1)])
P22=[mul(a,b) for a in P2 for b in P2]
P33=[mul(a,b) for a in P3 for b in P3b]
assert prod(P22,P33)==ideal([(6,0)])

