from math import gcd
def h(D):
    c=0; a=1
    while 3*a*a<=-D:
        for b in range(-a,a+1):
            if (b*b-D)%(4*a)==0:
                cc=(b*b-D)//(4*a)
                if cc<a or gcd(gcd(a,abs(b)),cc)!=1: continue
                if b<0 and (abs(b)==a or a==cc): continue
                c+=1
        a+=1
    return c
assert h(-20)==2 and h(-23)==3 and h(-163)==1 and h(-56)==4

