import cmath, math
w=cmath.exp(2j*math.pi/3)
def primary(p):
    out=[]
    B=math.isqrt(4*p)+1
    for a in range(-B,B+1):
        for b in range(-B,B+1):
            if a*a-a*b+b*b==p and a%3==2 and b%3==0: out.append((a,b))
    return out
def chi_pi(pi,alpha):
    # cubic residue symbol (alpha/pi)_3 for pi=a+b w of prime norm p, alpha=(c,d)
    a,b=pi; p=a*a-a*b+b*b
    r=(-a*pow(b,-1,p))%p
    c,d=alpha; n=(c+d*r)%p
    if n==0: return 0
    v=pow(n,(p-1)//3,p)
    for k in range(3):
        if pow(r,k,p)==v: return k
    raise Exception
from sympy import primerange
Ps=[]
for p in primerange(7,200):
    if p%3==1: Ps+=primary(p)
for x in Ps:
    for y in Ps:
        nx=x[0]**2-x[0]*x[1]+x[1]**2; ny=y[0]**2-y[0]*y[1]+y[1]**2
        if nx!=ny: assert chi_pi(x,y)==chi_pi(y,x)

from sympy import jacobi_symbol
def kron(D,n):
    r=1
    while n%2==0:
        n//=2
        if D%2==0: return 0
        r*= 1 if D%8 in (1,7) else -1
    if n==1: return r
    return r*jacobi_symbol(D%n,n)
from sympy import divisors
def rQ(a,b,c,m):
    B=int((m)**0.5)+3
    return sum(1 for x in range(-B,B+1) for y in range(-B,B+1) if a*x*x+b*x*y+c*y*y==m)
for m in range(1,401):
    aK=sum(kron(-20,d) for d in divisors(m))
    assert 2*aK==rQ(1,0,5,m)+rQ(2,2,3,m)
assert sum(kron(-20,d) for d in divisors(6))==2 and sum(kron(-20,d) for d in divisors(3))==2
assert rQ(1,0,5,3)==0 and kron(-20,3)==1

import mpmath as mp
mp.mp.dps=30
GR=lambda s: mp.pi**(-s/2)*mp.gamma(s/2)
GC=lambda s: 2*(2*mp.pi)**(-s)*mp.gamma(s)
def Lam(s,chi,D,r1,r2): return abs(D)**(s/2)*GR(s)**r1*GC(s)**r2*mp.zeta(s)*mp.dirichlet(s,chi)
for s in [mp.mpf('0.3'), mp.mpc('0.2','5'), mp.mpc('-1.5','2')]:
    for chi,D,r1,r2 in [([0,1,0,-1],-4,0,1),([0,1,-1,-1,1],5,2,0)]:
        a=Lam(s,chi,D,r1,r2); b=Lam(1-s,chi,D,r1,r2)
        assert abs(a-b)<1e-15*max(1,abs(a))

